def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        match = re.search(r"<([^<>]*)>", value)
        email = (match.group(1) if match else value).strip().lower()

        if email.count("@") != 1:
            return ""

        local, domain = email.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"[^0-9]", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"[0-9]{5}-[0-9]{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"[0-9]{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"[0-9]{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        return value.title() if value.isupper() or value.islower() else value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    contacts = []
    for input_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        contacts.append({
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": row["opted_out"].strip().lower() in {
                "y", "yes", "true", "1"
            },
            "updated": parse_updated(row["updated"]),
            "input_index": input_index,
        })

    # Union-find captures transitive matches.
    parent = list(range(len(contacts)))
    size = [1] * len(contacts)

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left, right = find(left), find(right)
        if left == right:
            return
        if size[left] < size[right]:
            left, right = right, left
        parent[right] = left
        size[left] += size[right]

    email_seen = {}
    phone_name_seen = {}

    for index, contact in enumerate(contacts):
        email = contact["email"]
        if email:
            if email in email_seen:
                union(index, email_seen[email])
            else:
                email_seen[email] = index

        if contact["phone"] and contact["last_name"]:
            key = (contact["phone"], contact["last_name"].casefold())
            if key in phone_name_seen:
                union(index, phone_name_seen[key])
            else:
                phone_name_seen[key] = index

    groups = {}
    for index, contact in enumerate(contacts):
        groups.setdefault(find(index), []).append(contact)

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(contact["input_index"] for contact in group),
    )

    output = []
    fields = ("first_name", "last_name", "zip", "email", "phone", "source")

    for group in ordered_groups:
        # Higher priority: manual source, newer timestamp, earlier input row.
        ranked = sorted(
            group,
            key=lambda contact: (
                contact["source"] == "manual",
                contact["updated"],
                -contact["input_index"],
            ),
            reverse=True,
        )

        person = {
            field: next(
                (contact[field] for contact in ranked if contact[field]),
                "",
            )
            for field in fields
        }

        tags = set()
        for contact in group:
            tags.update(contact["tags"])

        person["tags"] = ";".join(sorted(tags))
        person["opted_out"] = "Y" if any(
            contact["opted_out"] for contact in group
        ) else "N"
        person["updated"] = max(
            contact["updated"] for contact in group
        ).strftime("%Y-%m-%d")

        output.append(person)

    return output
